    const twelve = { ...cmd, userRole: 'LAB_ADMIN' as const, endAt: '2026-08-10T21:00:00.000Z' };  // 12 ชม.
    assert.equal(replay(createBooking(twelve, []))?.status, 'REQUESTED');
  });

  test('REQ-13 LAB_ADMIN จอง 12 ชม. 15 นาที -> 422', () => {
    const over = { ...cmd, userRole: 'LAB_ADMIN' as const, endAt: '2026-08-10T21:15:00.000Z' };
    assert.throws(
      () => createBooking(over, []),
      (e: DomainError) => e.httpStatus === 422,
    );
  });
});

